    [Theory][InlineData("APPROVE")][InlineData("REJECT")]
    public async Task ActualPaymentHandoffRequiresNativeDecisionAndPreservesSeparateProcessAndProductionOwners(string decision)
    {
        using var validation=CompanySalesInvoiceValidation.Enter();Reset();var p=shared.Base.Posting;var production=p.Reviewed.Draft.Native;var lifecycle=new CompanyProcessStartTests.Fixture("ConfiguredCompanyRole");lifecycle.Definition.ENTITY_TYPE="AR_PAYMENT";
        ProcessStepDefinition Step(string id,int order,bool approval)=>new(){StepId=id,StepName=id,SequenceNumber=order,RequiredRoles=["ConfiguredCompanyRole"],RequiresApproval=approval,StepType=approval?"APPROVAL":"ACTION",StepConfiguration=new(){[CompanyAccountingStepEvidence.ConfigurationKey]=approval?CompanyAccountingSourceTypes.Approval("AR_PAYMENT"):CompanyAccountingSourceTypes.RejectionReview("AR_PAYMENT")}};
        lifecycle.Definition.PROCESS_CONFIG_JSON=JsonSerializer.Serialize(new{Steps=new[]{Step("PAYMENT_REVIEW",1,true),Step("PAYMENT_REJECTION_REVIEW",2,false)}});CompanyStepCommandTests.ConfigureUpdates(lifecycle);
        static object[] Rows(List<object> rows,string table,List<AppFilter> filters)=>rows.Where(row=>row.GetType().Name==table && filters.All(filter=>row.GetType().GetProperty(filter.FieldName)?.GetValue(row)?.ToString()==filter.FilterValue)).Select(row=>JsonSerializer.Deserialize(JsonSerializer.Serialize(row),row.GetType())!).ToArray();var productionReads=0;var lifecycleReads=0;
        production.Source.Setup(value=>value.GetEntity(It.IsAny<string>(),It.IsAny<List<AppFilter>>())).Returns((string table,List<AppFilter> filters)=>{Assert.Null(((ITaskTransactionEvidence)lifecycle.Native.Source.Object).ActiveTransaction);productionReads++;return Rows(production.Rows,table,filters);});production.Source.Setup(value=>value.GetEntityAsync(It.IsAny<string>(),It.IsAny<List<AppFilter>>())).ReturnsAsync((string table,List<AppFilter> filters)=>{Assert.Null(((ITaskTransactionEvidence)lifecycle.Native.Source.Object).ActiveTransaction);productionReads++;return Rows(production.Rows,table,filters);});
        lifecycle.Native.Source.Setup(value=>value.GetEntity(It.IsAny<string>(),It.IsAny<List<AppFilter>>())).Returns((string table,List<AppFilter> filters)=>{Assert.Null(((ITaskTransactionEvidence)production.Source.Object).ActiveTransaction);lifecycleReads++;return Rows(lifecycle.Native.Rows,table,filters);});lifecycle.Native.Source.Setup(value=>value.GetEntityAsync(It.IsAny<string>(),It.IsAny<List<AppFilter>>())).ReturnsAsync((string table,List<AppFilter> filters)=>{Assert.Null(((ITaskTransactionEvidence)production.Source.Object).ActiveTransaction);lifecycleReads++;return Rows(lifecycle.Native.Rows,table,filters);});
        var grants=new[]{"Accounting.View","Accounting.ReviewSalesPaymentSource","Accounting.PrepareSalesPayment","Accounting.ReviewSalesPayment","Accounting.RecordSalesPaymentDecision","Workflow.Start","Workflow.Approve","Workflow.Execute"};
        await using var host=await shared.Base.Baseline.NativeFixture.Receivable.Data.Invoice.Data.Start(permissions:grants,configure:(services,context)=>{context.Actor="collector";context.PolicyBinding=shared.Review.Current.Ledger.BindingRevision;context.StartBinding=shared.Review.Current.Ledger.BindingRevision;context.FixedProcess=lifecycle.Service;services.AddSingleton<IARService>(p.AR);services.AddScoped<CompanySalesReceivableReads>();services.AddSingleton(p.Reviewed.Draft.Service);});void Actor(string actor){host.Context.Actor=actor;host.Client.DefaultRequestHeaders.Remove("X-Test-Actor");host.Client.DefaultRequestHeaders.Add("X-Test-Actor",actor);}void ReleaseReadHistory(){production.Source.Invocations.Clear();production.Editor.Invocations.Clear();lifecycle.Native.Source.Invocations.Clear();}
        Actor("collector");using var maker=CompanyGLAccountHttpTests.Selected(actor:"collector",grants:grants);var makerClient=CompanySalesReceivableWorkflowTests.Fixture.Processes(host,maker);var originalRevision=ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(shared.Draft));var query=new CompanyAccountingProcessStartQuery("definition","AR_PAYMENT",shared.Draft.AR_PAYMENT_ID,originalRevision);
        var reviewedStart=await makerClient.ReviewCompanyAccountingStartAsync(query);Assert.Equal("collector",reviewedStart.SourcePreparerUserId);ReleaseReadHistory();var start=await makerClient.StartCompanyAccountingAsync(reviewedStart.CreateIntent(Guid.NewGuid().ToString("N")));Assert.Equal("AR_PAYMENT",start.EntityType);Assert.All(lifecycle.Native.Rows.OfType<CROSS_PERSONA_TASK>(),task=>Assert.Equal(WorkflowTaskRoute.For("COMPANY_ACCOUNTING",start.InstanceId,"AR_PAYMENT"),task.ROUTE));ReleaseReadHistory();
        Actor("controller");using var controller=CompanyGLAccountHttpTests.Selected(actor:"controller",grants:grants);var client=CompanySalesReceivableWorkflowTests.Fixture.Processes(host,controller);var before=(await client.ReviewCompanyAccountingStepAsync(start.InstanceId))!;Assert.False(before.Eligible);Assert.Equal("SALES_PAYMENT_APPROVAL_REQUIRED",before.Eligibility);ReleaseReadHistory();var accounting=CompanyGLAccountHttpTests.Client(host.Client,controller);var review=await accounting.GetCompanySalesPaymentReviewAsync(shared.Draft.AR_PAYMENT_ID);ReleaseReadHistory();await accounting.RecordCompanySalesPaymentReviewAsync(new(Guid.NewGuid().ToString("N"),review,decision,decision=="APPROVE"?"CONFIRMED":"ISSUE","Original amount evidence","CONFIRMED","Original receipt evidence","Assigned controller payment decision"));ReleaseReadHistory();
        var step=(await client.ReviewCompanyAccountingStepAsync(start.InstanceId))!;Assert.Equal(decision=="APPROVE"?"ELIGIBLE":"SALES_PAYMENT_REJECTION_RECORDED",step.Eligibility);Assert.Equal(originalRevision,step.SourceRevision);ReleaseReadHistory();var observed=await client.GetCompanySalesPaymentSourceAsync(start.InstanceId);observed.Require(shared.Review.Current.Ledger.Company,"controller",start.InstanceId);Assert.Equal(decision=="APPROVE"?"APPROVED":"REJECTED",observed.Payment.Payment.Status);Assert.DoesNotContain("COMMAND_JSON",JsonSerializer.Serialize(observed));ReleaseReadHistory();
        var command=new CompanyAccountingStepCommand(step,Guid.NewGuid().ToString("N"),"Observe original native payment decision",decision=="REJECT"?CompanyAccountingSourceTypes.RejectionRoute("AR_PAYMENT"):null);var receipt=await client.CompleteCompanyAccountingStepAsync(command);receipt.Require(command);ReleaseReadHistory();var writes=lifecycle.Native.Writes;Assert.Equal(JsonSerializer.Serialize(receipt),JsonSerializer.Serialize(await client.CompleteCompanyAccountingStepAsync(command)));Assert.Equal(writes,lifecycle.Native.Writes);ReleaseReadHistory();
        if(decision=="REJECT"){var approval=Assert.Single(lifecycle.Native.Rows.OfType<PROCESS_APPROVAL>());Assert.Equal("SALES_PAYMENT_DECISION",approval.APPROVAL_TYPE);Assert.Equal("REJECTED",approval.APPROVAL_STATUS);Actor("collector");var makerStep=(await makerClient.ReviewCompanyAccountingStepAsync(start.InstanceId))!;Assert.True(makerStep.Eligible);Assert.False(makerStep.RequiresIndependentActor);ReleaseReadHistory();await makerClient.CompleteCompanyAccountingStepAsync(new(makerStep,Guid.NewGuid().ToString("N"),"Original maker acknowledged payment rejection"));}
        Assert.Equal(ProcessStatus.COMPLETED,(await lifecycle.Service.GetProcessInstanceAsync(start.InstanceId))!.Status);Assert.Equal(2,production.Writes);Assert.True(productionReads>0);Assert.True(lifecycleReads>0);Assert.Equal(JsonSerializer.Serialize(shared.Rows.Where(row=>row is AR_INVOICE or GL_ENTRY)),JsonSerializer.Serialize(production.Rows.Where(row=>row is AR_INVOICE or GL_ENTRY)));
